ALTER TYPE "OrganizationSequenceType" ADD VALUE 'QUOTATION';
CREATE TYPE "QuotationStatus" AS ENUM ('DRAFT','ISSUED','ACCEPTED','REJECTED','EXPIRED','CANCELLED');
CREATE TABLE "quotations" ("id" UUID NOT NULL,"organization_id" UUID NOT NULL,"quotation_number" VARCHAR(64) NOT NULL,"customer_id" UUID NOT NULL,"status" "QuotationStatus" NOT NULL DEFAULT 'DRAFT',"issue_date" DATE,"valid_until" DATE NOT NULL,"currency_code" CHAR(3) NOT NULL,"subtotal" DECIMAL(19,4) NOT NULL DEFAULT 0,"grand_total" DECIMAL(19,4) NOT NULL DEFAULT 0,"created_at" TIMESTAMPTZ(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updated_at" TIMESTAMPTZ(6) NOT NULL,CONSTRAINT "quotations_pkey" PRIMARY KEY("id"));
CREATE TABLE "quotation_items" ("id" UUID NOT NULL,"quotation_id" UUID NOT NULL,"description" VARCHAR(2000) NOT NULL,"quantity" INTEGER NOT NULL,"unit_price" DECIMAL(19,4) NOT NULL,"line_total" DECIMAL(19,4) NOT NULL,"created_at" TIMESTAMPTZ(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "quotation_items_pkey" PRIMARY KEY("id"),CONSTRAINT "quotation_items_quantity_check" CHECK ("quantity">0));
CREATE UNIQUE INDEX "quotations_organization_id_quotation_number_key" ON "quotations"("organization_id","quotation_number"); CREATE INDEX "quotations_organization_id_status_created_at_idx" ON "quotations"("organization_id","status","created_at"); CREATE INDEX "quotation_items_quotation_id_idx" ON "quotation_items"("quotation_id");
ALTER TABLE "quotations" ADD CONSTRAINT "quotations_organization_fkey" FOREIGN KEY("organization_id") REFERENCES "organizations"("id") ON DELETE RESTRICT ON UPDATE CASCADE; ALTER TABLE "quotations" ADD CONSTRAINT "quotations_customer_fkey" FOREIGN KEY("organization_id","customer_id") REFERENCES "customers"("organization_id","id") ON DELETE RESTRICT ON UPDATE CASCADE; ALTER TABLE "quotation_items" ADD CONSTRAINT "quotation_items_quotation_fkey" FOREIGN KEY("quotation_id") REFERENCES "quotations"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
